CREATE FUNCTION calculate(x INTEGER)
RETURNS INTEGER
LANGUAGE JAVA
HANDLER = 'Calculator.single'
AS $$
class Calculator {
  public static int single(int x) {
    return x * 2;
  }
}
$$

CREATE FUNCTION calculate(x INTEGER, y INTEGER)
RETURNS INTEGER
LANGUAGE JAVA
HANDLER = 'Calculator.dual'
AS $$
class Calculator {
  public static int dual(int x, int y) {
    return x + y;
  }
}
$$

